1	use anyhow::{Context, Result};
2	use git2::{build::RepoBuilder, Cred, FetchOptions, RemoteCallbacks, Repository, Signature};
3	use std::path::Path;
4	use std::process::Command;
5	use tracing::{debug, info};
6	
7	/// Redact credentials/tokens from a git URL for safe display/logging.
8	///
9	/// Handles formats like:
10	/// - `https://ghp_TOKEN@github.com/user/repo.git` -> `https://***@github.com/user/repo.git`
11	/// - `https://user:password@github.com/user/repo.git` -> `https://***@github.com/user/repo.git`
12	/// - `https://oauth2:TOKEN@github.com/user/repo.git` -> `https://***@github.com/user/repo.git`
13	/// - `https://github.com/user/repo.git` -> unchanged
14	#[must_use]
15	pub fn redact_credentials(url: &str) -> String {
16	    if let Some(protocol_end) = url.find("://") {
17	        let after_protocol = &url[protocol_end + 3..];
18	        if let Some(at_pos) = after_protocol.find('@') {
19	            let host_and_path = &after_protocol[at_pos + 1..];
20	            return format!("{}://***@{}", &url[..protocol_end], host_and_path);
21	        }
22	    }
23	    url.to_string()
24	}
25	
26	/// Remove credentials from a git URL.
27	///
28	/// Transforms:
29	/// - `https://token@github.com/user/repo.git` -> `https://github.com/user/repo.git`
30	/// - `https://user:pass@github.com/user/repo.git` -> `https://github.com/user/repo.git`
31	#[must_use]
32	pub fn remove_credentials_from_url(url: &str) -> String {
33	    if let Some(protocol_end) = url.find("://") {
34	        let after_protocol = &url[protocol_end + 3..];
35	        if let Some(at_pos) = after_protocol.find('@') {
36	            let host_and_path = &after_protocol[at_pos + 1..];
37	            return format!("{}://{}", &url[..protocol_end], host_and_path);
38	        }
39	    }
40	    url.to_string()
41	}
42	
43	/// Add credentials to a git URL.
44	///
45	/// Transforms:
46	/// - `https://github.com/user/repo.git` + token -> `https://token@github.com/user/repo.git`
47	///
48	/// If URL already has credentials, they are replaced.
49	#[must_use]
50	pub fn add_credentials_to_url(url: &str, token: &str) -> String {
51	    // First remove any existing credentials
52	    let clean_url = remove_credentials_from_url(url);
53	
54	    // Then add the new token
55	    if clean_url.starts_with("https://") {
56	        clean_url.replacen("https://", &format!("https://{token}@"), 1)
57	    } else {
58	        clean_url
59	    }
60	}
61	
62	/// Check if a URL has embedded credentials.
63	#[must_use]
64	pub fn url_has_credentials(url: &str) -> bool {
65	    if let Some(protocol_end) = url.find("://") {
66	        let after_protocol = &url[protocol_end + 3..];
67	        return after_protocol.contains('@');
68	    }
69	    false
70	}
71	
72	/// Check if a URL is an SSH-based git URL.
73	///
74	/// Returns true for URLs like:
75	/// - `git@github.com:user/repo.git`
76	/// - `ssh://git@github.com/user/repo.git`
77	#[must_use]
78	pub fn is_ssh_url(url: &str) -> bool {
79	    url.starts_with("git@") || url.starts_with("ssh://")
80	}
