/// - `https://oauth2:TOKEN@github.com/user/repo.git` -> `https://***@github.com/user/repo.git`
/// - `https://github.com/user/repo.git` -> unchanged
#[must_use]
pub fn redact_credentials(url: &str) -> String {
    if let Some(protocol_end) = url.find("://") {
