78	        let git_mgr = match GitManager::open_or_init(repo_path) {
79	            Ok(mgr) => mgr,
80	            Err(_) => return result,
81	        };
82	
83	        // Get changed files (this includes both uncommitted and unpushed)
84	        if let Ok(files) = git_mgr.get_changed_files() {
85	            result.has_changes = !files.is_empty();
86	            result.changed_files = files;
87	        } else {
