95	                .unwrap_or_else(|| "main".to_string());
96	            let has_unpushed = git_mgr
97	                .has_unpushed_commits("origin", &branch)
98	                .unwrap_or(false);
99	
100	            result.has_changes = has_uncommitted || has_unpushed;
101	        }
102	
103	        result
